-- Hyprland-run windowrule
hl.window_rule({
	name = "move-hyprland-run",
	match = { class = "hyprland-run" },

	move = "20 monitor_h-120",
	float = true,
})

local function compact_workspaces()
	local workspaces = hl.get_workspaces()

	local occupied = {}

	for _, ws in ipairs(workspaces) do
		if ws.id > 0 and ws.windows > 0 then
			table.insert(occupied, ws)
		end
	end

	table.sort(occupied, function(a, b)
		return a.id < b.id
	end)

	for i, ws in ipairs(occupied) do
		if ws.id ~= i then
			hl.dispatch(hl.dsp.workspace.change_id({
				workspace = ws,
				id = 10000 + i,
			}))
		end
	end

	for i, ws in ipairs(occupied) do
		hl.dispatch(hl.dsp.workspace.change_id({
			workspace = 10000 + i,
			id = i,
		}))
	end

	-- Force Waybar to refresh its workspace state
	hl.dsp.exec_cmd("pkill -SIGUSR2 waybar")
end

hl.on("workspace.removed", compact_workspaces)
